// POST /orders — state-changing handler with an exactly-once contract
export async function createOrder(req: Request): Promise<Response> {
  const parsed = OrderSchema.safeParse(await req.json())
  if (!parsed.success) {
    return json(400, { ok: false, error: 'INVALID_BODY', detail: parsed.error.issues })
  }

  const caller = await authorize(req)               // verify token + ownership
  if (!caller) return json(401, { ok: false, error: 'UNAUTHENTICATED' })
  if (caller.id !== parsed.data.customerId) {
    return json(403, { ok: false, error: 'FORBIDDEN' })
  }

  const key = req.headers.get('Idempotency-Key')
  if (!key) return json(400, { ok: false, error: 'IDEMPOTENCY_KEY_REQUIRED' })

  return db.transaction(async (tx) => {
    const prior = await tx.idempotency.find(key)
    if (prior) return json(200, prior.response)     // replay the FIRST result
    const order = await tx.orders.insert(parsed.data)
    const body = { ok: true, data: { orderId: order.id } }
    await tx.idempotency.save(key, body)            // same txn → commit together
    return json(201, body)
  })                                                 // any throw → full rollback
}

