  cartId: z.string().uuid(),
  items: z.array(z.object({
    sku: z.string().min(1),
    qty: z.number().int().positive(),
    unitPrice: z.number().int().nonnegative(), // cents
  })).min(1),
  total: z.number().int().nonnegative(),       // cents, client-asserted — reject unknown fields, no isAdmin smuggling
})

// Invariant the resource must satisfy before it persists.
export function assertOrderInvariant(req: CreateOrderRequest): void {
  const sum = req.items.reduce((n, i) => n + i.qty * i.unitPrice, 0)
  if (sum !== req.total) throw new ContractError('total != sum(items)')
}

