import { z } from 'zod'

export const CreatePaymentRequest = z.object({
  amountCents: z.number().int().positive(),
  currency: z.enum(['USD', 'EUR', 'GBP']),
  idempotencyKey: z.string().uuid(),
})

export const PaymentResponse = z.object({
  id: z.string().uuid(),
  status: z.enum(['succeeded', 'pending']),
  amountCents: z.number().int(),
})

export async function createPayment(rawBody: unknown, db: Db) {
  const parsed = CreatePaymentRequest.safeParse(rawBody)
  if (!parsed.success) {
    return { status: 422, body: { error: 'invalid_request', fields: parsed.error.flatten().fieldErrors } }
  }
  const req = parsed.data

  const existing = await db.findPaymentByKey(req.idempotencyKey)
  if (existing) return { status: 200, body: PaymentResponse.parse(existing) }

  const payment = await db.tx(async (t) => {
    return t.insertPayment({ ...req, status: 'succeeded' })
  })
  return { status: 201, body: PaymentResponse.parse(payment) }
}

