// The ONE error shape (RFC 9457 Problem Details + a field-level errors[]).
interface FieldError { field: string; code: string; message: string }
interface ProblemDetails {
  type: string        // stable URI naming the error class
  title: string       // short, human, NOT the stack trace
  status: number      // mirrors the HTTP status line
  detail?: string
  errors?: FieldError[]
}

const CreateOrder = z.object({
  sku: z.string().min(1),
  quantity: z.number().int().positive(),
})

async function createOrder(req: Request): Promise<Response> {
  // GATE 1 — semantic validation. ONE place, structured failure.
  const parsed = CreateOrder.safeParse(await req.json())
  if (!parsed.success) {
    return problem(422, 'about:blank#invalid-order', 'Order failed validation',
      parsed.error.issues.map((i) => ({
        field: i.path.join('.'), code: i.code, message: i.message,
      })))
  }
  // GATE 2 — idempotency: a replayed key returns the FIRST result, no 2nd write.
  const key = req.headers.get('Idempotency-Key')
  const prior = key ? await idem.lookup(key) : null
  if (prior) return prior.response

  // GATE 3 — mutate inside a transaction; a conflict is a 409, not a 500.
  try {
    const order = await db.tx((t) => t.orders.insert(parsed.data))
    const res = json(201, order)
    if (key) await idem.store(key, res)   // record BEFORE returning
    return res
  } catch (e) {
    if (e instanceof ConflictError)
      return problem(409, 'about:blank#stock-conflict', 'Insufficient stock')
    throw e   // unknown → 500 by the framework, body still a ProblemDetails
  }
}

