async def create_payment(body: PaymentIn, idem_key: str = Header(...), user=Depends(auth)):
    if body.amount <= 0:
        raise HTTPException(422, "amount must be positive")
    if not user.can_charge(body.account_id):
        raise HTTPException(403, "not allowed to charge this account")

    prior = await store.get_by_idem_key(idem_key)
    if prior is not None:
        return JSONResponse(prior.body, status_code=prior.status)  # replay, no re-charge

