const SORTABLE = { created_at: 'created_at', total: 'total_cents' } as const
const MAX_LIMIT = 100

export async function listOrders(req: Request) {
  const q = new URL(req.url).searchParams
  const limit = Math.min(Number(q.get('limit') ?? 20) || 20, MAX_LIMIT)
  const sortKey = SORTABLE[q.get('sort') as keyof typeof SORTABLE] ?? 'created_at'
  const status = q.get('status') // filter, bound-param below
  const cursor = decodeCursor(q.get('cursor')) // -> { key, id } | null

  const rows = await sql`
    SELECT id, status, total_cents, created_at FROM orders
    WHERE customer_id = ${req.customerId}
      ${status ? sql`AND status = ${status}` : sql``}
      ${cursor ? sql`AND (${sql(sortKey)}, id) < (${cursor.key}, ${cursor.id})` : sql``}
    ORDER BY ${sql(sortKey)} DESC, id DESC
    LIMIT ${limit + 1}`

  const hasMore = rows.length > limit
  const items = hasMore ? rows.slice(0, limit) : rows
  const last = items[items.length - 1]
  return Response.json({
    items,
    next_cursor: hasMore ? encodeCursor(last[sortKey], last.id) : null,
  })
}

