async function createCharge(req: ChargeRequest): Promise<ChargeResult> {
  const key = req.headers['idempotency-key']
  if (!key) throw new HttpError(400, 'Idempotency-Key required')

  return db.transaction(async (tx) => {
    const existing = await tx.idempotencyKeys.find(key)
    if (existing) return existing.result          // replay → first response

    const charge = await tx.charges.insert({ amount: req.amount })
    const result = { id: charge.id, status: 'captured' }

