export async function getOrder(req: Request, res: Response) {
  // principal is set by the authn middleware from the verified JWT — never the body
  const principal = req.principal
  if (!principal) return res.status(401).json({ error: 'unauthenticated' })

  const orderId = Number(req.params.id)
  const order = await db.orders.findById(orderId)
  if (!order) return res.status(404).json({ error: 'not_found' })

  // THE BOUNDARY: this principal must own THIS object
  if (order.customerId !== principal.customerId) {
    log.warn('authz_denied', { principal: principal.id, object: orderId })
    return res.status(403).json({ error: 'forbidden' })
  }

  return res.status(200).json(toOrderDto(order))
}

