// 1. The boundary: the service knows ONLY this shape.
export interface OrderRepository {
  findByIdempotencyKey(key: string): Promise<Order | null>
  save(order: Order, idempotencyKey: string): Promise<Order>
}

// 2. Service depends on the interface — no SQL, no ORM, no table names.
export class OrderService {
  constructor(private readonly orders: OrderRepository) {}

  async place(cmd: PlaceOrder, idempotencyKey: string): Promise<Order> {
    const existing = await this.orders.findByIdempotencyKey(idempotencyKey)
    if (existing) return existing // replay → return prior result, no re-write
    return this.orders.save(Order.fromCommand(cmd), idempotencyKey)
  }
}

// 3. One implementation owns persistence: tx + idempotency + rollback.
export class PgOrderRepository implements OrderRepository {
  constructor(private readonly db: Pool) {}

  async save(order: Order, idempotencyKey: string): Promise<Order> {
    const tx = await this.db.connect()
    try {
      await tx.query('BEGIN')
      await tx.query(
        'INSERT INTO orders (id, total, idempotency_key) VALUES ($1,$2,$3)',
        [order.id, order.total, idempotencyKey],
      )
      await tx.query('COMMIT')
      return order
    } catch (err) {
      await tx.query('ROLLBACK') // partial write is impossible past here
      throw err
    } finally {
      tx.release()
    }
  }
  // findByIdempotencyKey omitted for brevity
}

