import { z } from 'zod'

// Tolerant reader: v2 ADDS shippingTier, but it is OPTIONAL on the wire.
// Old v1 callers omit it entirely and must still succeed.
const OrderRequestV2 = z.object({
  itemId: z.string(),
  qty: z.number().int().positive(),
  shippingTier: z.enum(['standard', 'express']).optional(),
})

// Internal shape the handler actually uses — shippingTier is always present.
type InternalOrder = { itemId: string; qty: number; shippingTier: 'standard' | 'express' }

// The upgrade seam: fill the default for callers that never sent the field.
function upgrade(body: z.infer<typeof OrderRequestV2>): InternalOrder {
  return { ...body, shippingTier: body.shippingTier ?? 'standard' }
}

export async function handleOrder(raw: unknown): Promise<{ id: string }> {
  const parsed = OrderRequestV2.parse(raw) // rejects garbage, tolerates missing shippingTier
  const order = upgrade(parsed)            // v1 body becomes a complete internal order
  return persist(order)                    // ONE persistence path for both versions
}

declare function persist(o: InternalOrder): Promise<{ id: string }>

