from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel, condecimal

router = APIRouter()

class TransferIn(BaseModel):
    to_account: str            # validated: non-empty, owned-bank format
    amount: condecimal(gt=0, max_digits=12, decimal_places=2)

@router.post("/accounts/{account_id}/transfer")
def transfer(account_id: str, body: TransferIn, caller=Depends(current_user)):
    # authorize the OBJECT, not just the session
    acct = db.fetch_one(
        "SELECT id, owner_id FROM accounts WHERE id = %s AND tenant_id = %s",
        [account_id, caller.tenant_id],
    )
    if acct is None or acct.owner_id != caller.id:
        raise HTTPException(status_code=404)        # 404, not 403: don't confirm existence
    with db.transaction():
        debit(acct.id, body.amount)
        credit(body.to_account, body.amount)
    log.info("transfer ok", account=acct.id, amount=str(body.amount))  # no PII, no full body
    return {"status": "ok"}

