const Body = z.object({ amountCents: z.number().int().positive(), currency: z.literal('usd') })

export async function postCharge(req: Request): Promise<Response> {
  return tracer.startActiveSpan('POST /charges', async (span) => {
    const key = req.headers.get('Idempotency-Key')
    if (!key) return json(400, { error: 'Idempotency-Key header required' })

    const actor = await authorize(req)              // auth boundary — 401/403 before any write
    if (!actor) return json(401, { error: 'unauthenticated' })

    const parsed = Body.safeParse(await req.json())  // validate at the boundary
    if (!parsed.success) return json(422, { error: 'invalid body', detail: parsed.error.issues })

    const replay = await idem.get(actor.id, key)     // exactly-once check
    if (replay) { span.setAttribute('idem.replay', true); return json(202, replay.result) }

    const result = await db.transaction(async (tx) => {     // ONE atomic unit
      const charge = await tx.charges.insert({ actorId: actor.id, ...parsed.data })
      await tx.idempotencyKeys.insert({ actorId: actor.id, key, result: { id: charge.id } }) // unique(actorId,key)
      await tx.outbox.insert({ topic: 'receipt.email', chargeId: charge.id })  // enqueue in-txn → no lost event
      return { id: charge.id }
    })
    return json(202, result)                          // 202: accepted; receipt email is async
  })
}

