// POST /v1/charges — the capstone slice
export async function createCharge(req: Request, res: Response) {
  const span = tracer.startSpan('createCharge', { requestId: req.id })
  // 1. Contract: validate the request body against the schema (fail fast, 422)
  const body = ChargeSchema.safeParse(req.body)
  if (!body.success) return res.status(422).json({ error: body.error.message })
  // 2. Auth boundary: the caller must own the account it is charging
  if (!can(req.actor, 'charge:create', body.data.accountId))
    return res.status(403).json({ error: 'forbidden' })
  const key = req.header('Idempotency-Key')
  if (!key) return res.status(400).json({ error: 'Idempotency-Key required' })
  try {
    // 3. Persistence + idempotency in ONE transaction
    const charge = await db.tx(async (t) => {
      const prior = await t.idempotency.find(key)
      if (prior) return prior.response          // replay: same key, same answer
      const c = await t.charges.insert(body.data) // the side effect
      await t.idempotency.insert(key, c)          // committed atomically with it
      return c
    })
    // 4. Async fulfillment AFTER commit (queue owns receipt + ledger; DLQ catches poison)
    await queue.publish('charge.created', { chargeId: charge.id, requestId: req.id })
    log.info({ requestId: req.id, chargeId: charge.id, replay: charge.replayed ?? false })
    return res.status(charge.replayed ? 200 : 201).json(charge)
  } catch (err) {
    log.error({ requestId: req.id, err: serialize(err) }) // transaction already rolled back
    return res.status(500).json({ error: 'charge_failed', requestId: req.id })
  } finally {
    span.end()
  }
}

